		\end{equation}
		where $\widehat\alpha=\min\{\alpha,1\}$.
		By \eqref{v1_control} and \eqref{v1_control_zero}, using orthogonality and the fact that $\alpha_0\le \alpha$, we have
		\begin{equation}
			\label{v1_control_new}
			\left( \fint_{\partial B_\rho} |v_1(y') - v_1(0)|^2 \, dS \right)^{\frac{1}{2}} \le \left(\frac{\varepsilon+\rho^2}{\varepsilon+R^2} \right)^{\widehat\alpha_0/2} \left( \fint_{\partial B_R} |v_1(y') - v_1(0)|^2 \, dS \right)^{\frac{1}{2}},
		\end{equation}
		where $\widehat\alpha_0=\min\{\alpha_0,1\}$.

		{ We denote
			$$
			\omega(\rho):= \nparallel\kern-.2em \bar{v} - (\bar{v})_{\partial B_{\rho}} \Vert_{L^2(\partial B_\rho)}
			$$
			and 
			$$
			\omega_0(\rho):= \nparallel\kern-.2em \bar{v} - \bar{v}(0) \Vert_{L^2(\partial B_\rho)}.
			$$}
		Combining \eqref{v1_control} and \eqref{v2_control} yields, using $\bar{v} = v_1$ on $\partial B_R$ and $\bar{v} = v_1 + v_2$,
		\begin{equation}
