		\begin{equation}\label{G2-2}
			\|G_2\|_{\varepsilon, \sigma-1, s, B_{R_0}}\le C \Big( \frac{1}{k_1} + \frac{1}{k_2} \Big), \quad \mbox{when } \gamma=1, \sigma\le 2s.
		\end{equation}
		Let $G:=G_1+G_2$.

		Next, we consider two separate cases: $\gamma\ne 1$ and $\gamma=1$.

		\textit{Case 1:} When $\gamma\ne 1$,
		by decreasing $\sigma$ if necessary, we may assume that $\sigma\le \beta$ (so that \eqref{G2-1} is satisfied for any $s>0$), and $1+\sigma-2s_0=\sigma\ne\widehat\alpha$, where $\widehat{\alpha} = \min\{\alpha, 1\}$.
		Then by \eqref{F_G1} and \eqref{G2-1} with $s=s_0$, the estimate \eqref{v_bar_L2_sphere_old} in Proposition \ref{prop_grad_v_bar_control} implies that 
		\begin{equation}\label{v_bar_decay}
			\nparallel\kern-.2em \bar{v} - (\bar{v})_{\partial B_{2\varepsilon^{1/2}}} \Vert_{L^2(\partial B_{2\varepsilon^{1/2}})}\le C \varepsilon^{\tilde{\alpha}/2},
		\end{equation}
		where $\tilde{\alpha} = \min\{\widehat\alpha , 1+ \sigma - 2s_0 \}$.

		Since $u$ is odd in $x_j$ for some $1 \le j \le n-1$, $\bar{v}$ is also odd in $x_j$. In particular, this implies
		$$
		(\bar{v})_{\partial B_R} = 0 \quad \forall R \in(0,R_0).
		$$
		Then by \eqref{v_bar_decay} and \eqref{v-v_bar_2}, we have
		\begin{equation}
			\begin{aligned}\label{v_L2_control}
				\nparallel\kern-.2em u \Vert_{L^2(\Omega_{2\varepsilon^{1/2}})} \le& C \nparallel\kern-.2em v \Vert_{L^2(Q_{2\varepsilon^{1/2} , \varepsilon})} \\
				\le& C( \nparallel\kern-.2em v-\bar{v} \Vert_{L^2(Q_{2\varepsilon^{1/2} , \varepsilon})} + \nparallel\kern-.2em \bar v \Vert_{L^2(Q_{2\varepsilon^{1/2} , \varepsilon})})\\
				\le& C \varepsilon^{\tilde\alpha/2}.
			\end{aligned}
		\end{equation}
		By \eqref{v_L2_control}, \eqref{gi_c_beta}, and \eqref{gradient-1/2a} with $g_1(0') = g_2(0') = 0$, we have
		$$
		\| \nabla u\|_{L^\infty (\Omega_{\varepsilon^{1/2}})} \le C\varepsilon^{\frac{\tilde\alpha-1}{2}}.
		$$
		Similarly, for any $R \in (\varepsilon^{1/2}, R_0/4)$,  the estimates \eqref{v_bar_L2_sphere_old} in Proposition \ref{prop_grad_v_bar_control} with $s=s_0$ and \eqref{v-v_bar} imply
		$$
		\nparallel\kern-.2em u \Vert_{L^2(\Omega_{4R}\setminus \Omega_{R/2})} \le C R^{\tilde{\alpha}}, 
		$$
		which implies, by \eqref{gradient-1/2a} with $g_1(0') = g_2(0') = 0$ and \eqref{gi_c_beta},
		$$
		\| \nabla u\|_{L^\infty (\Omega_{4R}\setminus \Omega_{R/2})} \le CR^{\tilde\alpha-1}
		$$
		for any $R \in (\varepsilon^{1/2}, R_0/4)$. Therefore, we have improved the upper bound $|\nabla u(x)| \le C(\varepsilon + |x'|^2)^{-s_0}$ to $|\nabla u(x)| \le C(\varepsilon + |x'|^2)^{\frac{\tilde{\alpha}-1}{2}}$, where $\frac{\tilde{\alpha}-1}{2} = \min\left\{0,\frac{\alpha - 1}{2}, -s_0 + \frac{\sigma}{2} \right\}$. If $-s_0 + \frac{\sigma}{2} <\min\left\{0, \frac{\alpha - 1}{2}\right\}$, we take $s_1 = s_0 - \frac{\sigma}{2}$ and repeat the argument above. Note that the improved upper bound $|\nabla u(x)| \le C(\varepsilon + |x'|^2)^{-s_1}$ implies \eqref{F_G1} with $s_1$ in place of $s_0$. Let $s_k=s_0-k\frac{\sigma}{2}$ for $k\in \mathbb{Z}_+$. We may decrease $\sigma$ if necessary so that $1+\sigma -2s_k\ne \widehat\alpha$ for any $k\in \mathbb{Z}_+$.
		After {repeating the argument finitely many times}, we obtain the estimate \eqref{grad_u_upperbound1} or \eqref{grad_u_upperbound2}.

		\textit{Case 2:} When $\gamma= 1$, we know that $\widehat\alpha=\min\{\alpha,1\}=1$. By decreasing $\sigma$ if necessary, we may assume that $\sigma=1/(N+1)$ for some large integer $N$. Let $s_0=1/2$ and $s_k=s_0-k\frac{\sigma}{2}$ for $k=1,2,\dots, N+1$. Then clearly $1+\sigma-2s_k<1$ 
		for $k=0,1,\dots,N-1$ { and ${s_{N+1}=0}$}. Similar to case 1, by \eqref{G2-2} in place of \eqref{G2-1} with $s=s_k$, $k=0,1,\dots, N-1$, we can iterate the estimate \eqref{v_bar_L2_sphere_old} in Proposition \ref{prop_grad_v_bar_control} to improve the upper bound
		$|\nabla u(x)| \le C(\varepsilon + |x'|^2)^{-s_0}$ to $|\nabla u(x)| \le C(\varepsilon + |x'|^2)^{-s_N}$. From the improved upper bound $|\nabla u(x)| \le C(\varepsilon + |x'|^2)^{-s_N}$, one can obtain estimate \eqref{F_G1} with $s_N$ in place of $s_0$. Namely, we have
		\begin{equation}\label{F_G11}
			\|F\|_{\varepsilon, \sigma, s_N, B_{R_0}} + \|G_1\|_{\varepsilon, \sigma-1, s_N, B_{R_0}}\le C.
		\end{equation}

		We split $\bar v = v_1 + v_2$ such that $v_1$ satisfies
		\begin{equation*}
			\left\{
			\begin{aligned}
				\operatorname{div}((\varepsilon+|y'|^2)\nabla  v_1) - 2\gamma^{-1} v_1 &= \operatorname{div} F + G_1 \quad \mbox{in}~B_{R_0} \subset \mathbb{R}^{n-1},\\
				v_1 &= \bar{v}  \quad \mbox{on}~ \partial B_{R_0},
			\end{aligned}\right.
		\end{equation*}
		while $v_2$ satisfies
		\begin{equation*}
			\left\{
			\begin{aligned}
				\operatorname{div}((\varepsilon+|y'|^2)\nabla  v_2) - 2\gamma^{-1} v_2 &= G_2 \quad \mbox{in}~B_{R_0} \subset \mathbb{R}^{n-1},\\
				v_2 &= 0  \quad \mbox{on}~ \partial B_{R_0}.
			\end{aligned}\right.
		\end{equation*}


		Note that $1+\sigma-2s_{N}=1$. Then 
		by \eqref{F_G11}, \eqref{G2-2} with $s=s_N$, and \eqref{v-v_bar}, the estimate \eqref{v_bar_L2_sphere} in Proposition \ref{prop_grad_v_bar_control} implies that for any $R \in (0, R_0/2)$,
		\begin{equation}\label{est:v1v2}
			\left\{
			\begin{aligned}
				\nparallel\kern-.2em v_1 - (v_1)_{\partial B_R} \Vert_{L^2(\partial B_R)} &\le C R |\log R|,\\
				\nparallel\kern-.2em v_2 - (v_2)_{\partial B_R} \Vert_{L^2(\partial B_R)} &\le C \Big( \frac{1}{k_1} + \frac{1}{k_2} \Big) R |\log R|.
			\end{aligned}\right.
		\end{equation}
		Then
		$$
		\nparallel\kern-.2em {\bar v} \Vert_{L^2(\partial B_R)} \le \nparallel\kern-.2em v_1 - (v_1)_{\partial B_R} \Vert_{L^2(\partial B_R)} + \nparallel\kern-.2em v_2 - (v_2)_{\partial B_R} \Vert_{L^2(\partial B_R)} \le C R |\log R|.
		$$
		Therefore,
		\begin{equation*}
			\begin{aligned}                         
				\nparallel\kern-.2em u \Vert_{L^2(\Omega_{2\varepsilon^{1/2}})} \le& C \nparallel\kern-.2em v \Vert_{L^2(Q_{2\varepsilon^{1/2} , \varepsilon})} \\
				\le& C( \nparallel\kern-.2em v-\bar{v} \Vert_{L^2(Q_{2\varepsilon^{1/2} , \varepsilon})} + \nparallel\kern-.2em \bar v \Vert_{L^2(Q_{2\varepsilon^{1/2} , \varepsilon})})\\
				\le& C \varepsilon^{1/2} |\log \varepsilon|,
			\end{aligned}
		\end{equation*}
		and similarly
		$$
		\nparallel\kern-.2em u \Vert_{L^2(\Omega_{4R}\setminus \Omega_{R/2})} \le C R|\log R|
		$$
		for any $R \in (\varepsilon^{1/2}, R_0/4)$. Then by \eqref{gradient-1/2a} with $g_1(0') = g_2(0') = 0$ and \eqref{gi_c_beta}, we have
		\begin{equation}\label{est:Du_temp}
			|\nabla u (x)| \le C |\log (\varepsilon + |x'|^2)|.
		\end{equation}

		Recall that our goal is the estimate \eqref{grad_u_upperbound3}, which has a more precise dependence on $k_1, k_2$ than that in \eqref{est:Du_temp}. This can be achieved by improving the estimate for $v_1$ in \eqref{est:v1v2}. In fact, due to \eqref{est:Du_temp}, we have
		$$
		\|F\|_{\varepsilon, \sigma, s, B_{R_0}} + \|G_1\|_{\varepsilon, \sigma-1, s, B_{R_0}}\le C
		$$
		for any $s > 0$. We choose $s = \frac{\sigma}{4}$ so that $1 + \sigma - 2s =  1 + \sigma/2 > 1$. Then we can apply the estimate \eqref{v_bar_L2_sphere_old} in Proposition \ref{prop_grad_v_bar_control} to obtain
		$$
		\nparallel\kern-.2em v_1 - (v_1)_{\partial B_R} \Vert_{L^2(\partial B_R)} \le C R,
		$$
		which improves \eqref{est:v1v2} by removing the logarithmic factor. Then the estimate \eqref{grad_u_upperbound3} follows by repeating the same argument above.

\label{prop_grad_v_bar_control_2d}
		For $n = 2$, $0 \le s \le 1/2$, $\gamma > 0$, $\sigma> 0$, and $\varepsilon > 0$,
		let $\bar{v} \in H^1(B_{R_0})$ be a solution of
		\begin{equation*}

			\operatorname{div}((\varepsilon+|y'|^2)\nabla \bar v) -2\gamma^{-1}\bar{v} = \operatorname{div} F + G \quad\text{in}\,\,B_{R_0}\subset \mathbb{R}^{n-1},
		\end{equation*}
		where $F,G$ satisfy
		\begin{equation*}

			\|F\|_{\varepsilon, \sigma,s,B_{R_0}}< \infty , \quad \|G\|_{\varepsilon, \sigma-1,s,B_{R_0}} < \infty.
		\end{equation*}
		Let $\alpha$ be the constant given in \eqref{alpha_new}, and $\tilde\alpha := \min \{ \alpha, 1, 1 + \sigma - 2s \}$. There exists a positive constant $C$ depending only on $n$, $\sigma$, $s$, $R_0$, but independent of $\varepsilon$, such that for any $R \in (0, R_0/2)$, we have:
		\begin{itemize}
			\item[(i)] If $1+\sigma - 2s \neq \min\{\alpha,1\}$, then
			\begin{equation*}

				\begin{aligned}
					&\nparallel\kern-.2em \bar{v} - \bar{v}(0) \Vert_{L^2(\partial B_R)}\\
					&\le C(\|F\|_{\varepsilon, \sigma,s,B_{R_0}} + \|G\|_{\varepsilon, \sigma-1,s,B_{R_0}} +  \nparallel\kern-.2em \bar v - {\bar{v}(0)} \Vert_{L^2(\partial B_{R_0})})  R^{\tilde\alpha}.
				\end{aligned}
			\end{equation*}
			\item[(ii)] If $1+\sigma - 2s = \min\{\alpha,1\}$, then
			\begin{equation*}

				\begin{aligned}
					&\nparallel\kern-.2em \bar{v} - \bar{v}(0) \Vert_{L^2(\partial B_R)}\\
					&\le C(\|F\|_{\varepsilon, \sigma,s,B_{R_0}} + \|G\|_{\varepsilon, \sigma-1,s,B_{R_0}} +  \nparallel\kern-.2em \bar v -  {\bar{v}(0)} \Vert_{L^2(\partial B_{R_0})})  R^{\tilde\alpha}\log(R_0/R).
				\end{aligned}
			\end{equation*}
		\end{itemize}

\label{ODE_lemma}
		For $\varepsilon > 0$, $\gamma > 1$, $n \ge 2$, let $L$ be the operator defined as in \eqref{def_L}. There exists a unique solution $h \in C([0,1/2]) \cap C^\infty((0,1/2])$ of
		\begin{equation}
			\label{Homogeneous_ODE}
			Lh = 0, \quad 0 < r <1/2
		\end{equation}
		satisfying  $h(0) = 0$ and $h(1/2) = 1/2$.
		Moreover, there exists a positive constant $C(\varepsilon)$ depending only on $n$ and $\varepsilon$, such that
		\begin{equation}
			\label{h_bounds}
			r  < h(r) < \min\{ C(\varepsilon)r, r^\alpha\} \quad \mbox{for}~~0 < r < 1/2,
		\end{equation}
		where $\alpha$ is given by \eqref{alpha_new} and $h$ is strictly increasing in $[0,1/2]$.

\label{lemma_subsolution}
		For $\varepsilon > 0$, $\gamma > 1$, $n \ge 2$, let $h \in C([0,1/2]) \cap C^\infty((0,1/2])$ be the solution to \eqref{Homogeneous_ODE} and $\alpha$ be given by \eqref{alpha_new}. Then
		\begin{equation}\label{h_lowerbound}
			h(r) > {2^{\alpha-1}}\Big(r^\alpha - ({2}\sqrt\varepsilon)^{\alpha} \Big)_+, \quad r \in(0,1/2).
		\end{equation} Moreover, for some positive constants $C_1$, $C_2$ depending only on $n$, 
		\begin{equation}\label{h_upper_lower}
			C_1\varepsilon^{\frac{\alpha-1}{2}}r\le h(r)\le C_2\varepsilon^{\frac{\alpha-1}{2}}r, \quad r\in(0,{\min
            \{1/2,{4}\sqrt{\varepsilon}\}}).
		\end{equation}

Denote $v(r) = \Big(r^\alpha - (c\sqrt\varepsilon)^{\alpha} \Big)_+$ for some positive constant $c$ to be determined. When $r > c\sqrt\varepsilon$, a direct computation gives
\begin{align*}
 Lv =& - 2 \varepsilon \left( \alpha - \frac{1}{\gamma} \right) \frac{ r^{\alpha - 2}}{\varepsilon+r^2} + \left( \frac{n-2}{r^2} + \frac{2}{\gamma} \frac{1}{\varepsilon+r^2} \right) (c\sqrt\varepsilon)^{\alpha} \\
 \ge & \frac{c^{\alpha-2}\varepsilon^{\frac{\alpha}{2}}}{\varepsilon + r^2} \left( -2\alpha + \frac{2}{\gamma} + c^2\left( n-2 + \frac{2}{\gamma} \right) \right).
\end{align*}
When $n \ge 3$, it is clear that one can choose $c = 2$ such that $Lv > 0$. When $n = 2$,
$$
\alpha = \frac{-1 + \sqrt{1+ 8/\gamma}}{2} = \frac{8/\gamma}{2(1 + \sqrt{1+ 8/\gamma})} \le \frac{2}{\gamma}.
$$
Again, one can choose $c = 2$ such that $Lv > 0$. Then \eqref{h_lowerbound} follows from the maximum principle.

        For the proof of \eqref{h_upper_lower}, first we assume that  $0<\varepsilon<1/64$. We consider the following rescaling of $h$. For $s\in{[0,(2\sqrt{\varepsilon})^{-1}]}$, let $r=\sqrt{\varepsilon}s$ and $$\hat{h}(s):=\varepsilon^{-\alpha/2} h(r):= \varepsilon^{-\alpha/2} h(\sqrt{\varepsilon}s).$$ 
		Then $\hat{h}$ satisfies
		\begin{equation*}
			\hat{L}\hat{h}:=\hat{h}''(s)+\Big(\frac{n-2}{s}+\frac{2s}{1+s^2}\Big)\hat{h}'(s)-\Big(\frac{n-2}{s^2}+\frac{2}{\gamma}\frac{1}{1+s^2}\Big)\hat{h}(s)=0.
		\end{equation*}
		By Lemma \ref{ODE_lemma} and \eqref{h_lowerbound}, we have 
		$\hat{h}(0)=0$, $2^{2\alpha-1}(2^\alpha-1)\le\hat{h}(4)\le 4^\alpha$, and $\hat{h}(s)\le s^\alpha$ for $s\in[0,(2\sqrt{\varepsilon})^{-1}]$. 
		Since $\hat{L}s=\frac{2s}{1 + s^2} \left( 1 - \frac{1}{\gamma} \right) > 0$, by the maximum principle, one can obtain 
		\begin{equation}\label{low}
			\hat{h}(s)\ge \frac{\hat{h}(4)}{4}s\ge C_1s
            \quad \mbox{for } s\in(0,4)
		\end{equation}
		where $C_1$ is some positive constant depending only on $n$. Let $v = s - s^{3/2}/2$, by a direct computation,
		$$
		\left| {\hat L}v + \frac{1}{4} \Big( n - \frac{1}{2} \Big) s^{-\frac{1}{2}}  \right| \le 2 \Big( 1-\frac{1}{\gamma} \Big) s + \Big( 3-\frac{2}{\gamma} \Big) s^{\frac{3}{2}}{\le 2s + 3s^{3/2}}.
		$$
		Hence $\hat L v < 0$ in $(0, s_0)$, for some small $s_0=s_0(n)$.  By the maximum principle, we have 
		\begin{equation}\label{up1}
			\hat{h} \le \frac{\hat{h}(s_0)}{v(s_0)} v \le Cs\quad \text{in}\,\, (0,s_0),
		\end{equation}
		where $C = \frac{s_0^\alpha}{v(s_0)}$. On the other hand, for $s\in[s_0, 4)$,
		\begin{equation}\label{up2}
			\hat{h}(s)\le s^\alpha\le s_0^{\alpha-1}s.
		\end{equation}
		Combining \eqref{low}, \eqref{up1}, and \eqref{up2} yields 
		$$ C_1s\le \hat{h}(s)\le C_2s, \quad  \mbox{for } s\in(0,{4}),$$ where $C_1$, $C_2$ are some positive constants depending only on $n$. Therefore, \eqref{h_upper_lower} follows by reversing the scaling. {Finally, when $\varepsilon\ge {1/64}$, we apply a similar argument above with $h$ in place of $\hat h$ and $1/2$ in place of ${4}$. The lemma is proved.}

\label{linear_lower}
		For $n \ge 2$, $\gamma \ge 1$, $k_1>0$, $k_2>0$, $\varepsilon \in (0,1/4)$, let $\Omega = B_{5}$, $\mathcal{D}_1 , \mathcal{D}_2$ be balls of radius $1$ centered at $(0', 1 + \varepsilon/2)$ and $(0', -1- \varepsilon/2)$, respectively, $\varphi(x) = x_1$, and let $u$ be the solution of \eqref{robin}. Then we have
		\begin{equation*}
			u_+\ge x_1 \quad \mbox{in }\widetilde{\Omega}\cap\{x_1\ge0\}, \quad u_-\ge \frac{x_1}{1+k_i\gamma} \quad \mbox{in }\mathcal{D}_i\cap \{x_1\ge 0\}, \quad i=1,2,
		\end{equation*}
		\begin{equation*}
			u_+\le x_1 \quad \mbox{in }\widetilde{\Omega}\cap\{x_1\le0\}, \quad u_-\le \frac{x_1}{1+k_i\gamma} \quad \mbox{in }\mathcal{D}_i\cap \{x_1\le 0\}, \quad i=1,2.
		\end{equation*}

Recall that we assume $\mu = 1$. We will prove \eqref{grad_u_lower_bound} for $n \ge 3$ in the following four steps. The proof for $n = 2$ is similar and simpler. A brief remark on the case $n=2$ will be provided at the end.

		\textbf{Step 1.} By the elliptic theory, since $\widetilde\Omega$ is symmetric in $x_1$ and  $\varphi$ is odd in $x_1$, we know that {$u_+$ and $u_-$ are smooth up to the interfacial boundaries for fixed $\varepsilon>0$,} $|u| \le 5$, and $u$ is odd in $x_1$.
		Let $\tilde{u}$, $v$, $\bar{v}$ be defined as in Lemma \ref{lemma_reduction_2}.
		By Lemma \ref{lemma_reduction_2}, we know that $\bar{v}$ satisfies the equation \eqref{equation_v_bar_2}
		$$
		\operatorname{div}((\varepsilon+|y'|^2)\nabla \bar v) - 2\gamma^{-1} \bar{v}(y') = \operatorname{div} F + \tilde{G}_1+\tilde{G}_2 \quad \mbox{in}~B_{3/4} \subset \mathbb{R}^{n-1}.
		$$
		For simplicity of notation, we still denote $\tilde{G}_i$ by $G_i$.
		From the proof of Theorem \ref{thm_upperbound}, we know that
		\begin{equation}\label{prelim_estimate}
			|\nabla_{y'} v(y)| \le C(\varepsilon +|y'|^2)^{-1/2}, \quad |\partial_n v(y)| \le C (\varepsilon + |y'|^2)/ \varepsilon\quad \mbox{in}~ Q_{3/4,\varepsilon},
		\end{equation}
		where $Q_{3/4,\varepsilon}$ is defined in \eqref{Q_s_t}. Since both $\mathcal{D}_1$ and $\mathcal{D}_2$ are balls, $e^i$ from \eqref{a_ij_formula} can be bounded by $C|y'|^4$. Therefore by \eqref{FG_bound_b},  for $|y'| < 3/4$ we have
		\begin{equation}\label{FG_bound_2}
			\left\{
			\begin{aligned}
				&|F(y')| \le C\Big(|y'|(\varepsilon + |y'|^2) + |y'|^4 (\varepsilon +|y'|^2)^{-1/2}\Big), \\
				&|G_1(y')| \le C(\varepsilon + |y'|^2),\quad
				|G_2(y')| \le C|y'|^{1+\beta}.
			\end{aligned}\right.
		\end{equation}
		We denote $Y_{k,i}$ to be {a normalized spherical harmonic of degree $k$} so that $\{Y_{k,i}\}_{k,i}$ forms an orthonormal basis of $L^2(\mathbb{S}^{n-2})$, {$Y_{1,1}(\xi)=\xi_1/c_n$, where $c_n^2=\int_{\mathbb{S}^{n-2}}\xi_1^2\,d\xi$}, and we write $y' = (r ,\xi)$ {in polar coordinates}. Since $\bar v$ is odd with respect to $y_1$, and in particular $\bar{v}(0) = 0$, we have the following decomposition
		\begin{equation}
			\label{v_bar_expansion}
			\bar{v}(y') = V_{1,1}(r)Y_{1,1}(\xi) + \sum_{k=2}^\infty \sum_{i=1}^{N(k)} V_{k,i}(r)Y_{k,i}(\xi), \quad { y'} \in B_{3/4}\setminus\{0\},
		\end{equation}
		where $V_{k,i}(r) = \int_{\mathbb{S}^{n-2}} \bar{v}(r,\xi) Y_{k,i}(\xi) \, d\xi$ and $V_{k,i} \in C([0,3/4)) \cap C^\infty((0,3/4))$. Since $\bar{v}(0) = 0$ and $\varepsilon + |y'|^2$ is independent of $\xi$, we know that $V_{1,1}$ satisfies $V_{1,1}(0) = 0$, and
		\begin{equation*}
			LV_{1,1} = H_1(r)+H_2(r), \quad 0 < r <3/4,
		\end{equation*}
		where $L$ is the differential operator defined in \eqref{def_L},
		\begin{align*}
			H_1(r) &= \int_{\mathbb{S}^{n-2}} \frac{(\operatorname{div} F + G_1) Y_{1,1}(\xi)}{\varepsilon+r^2} \, d\xi \\
			&= \int_{\mathbb{S}^{n-2}} \frac{\partial_r F_r {+\frac{n-2}{r}F_r}
				+ \frac{1}{r} {\operatorname{div}_{\mathbb{S}^{n-2}}F_\xi} + G_1}{\varepsilon + r^2} Y_{1,1}(\xi) \, d\xi\\
			&= \partial_r \left(\int_{\mathbb{S}^{n-2}} \frac{F_r}{\varepsilon + r^2} Y_{1,1}(\xi) \, d\xi \right) \\
			&\quad + \int_{\mathbb{S}^{n-2}} {\Big(\frac{2r}{(\varepsilon+r^2)^2}+ \frac{n-2}{r(\varepsilon+r^2)}\Big)}F_r Y_{1,1}- \frac{{F_\xi\cdot\nabla_\xi Y_{1,1}}}{r(\varepsilon + r^2)} + \frac{G_1 Y_{1,1}}{\varepsilon+ r^2}\, d\xi\\
			&=: A'(r) + B(r), \quad 0 < r < 3/4.
		\end{align*}
		and
		\begin{align*}
			H_2(r) = \int_{\mathbb{S}^{n-2}} \frac{G_2 Y_{1,1}}{\varepsilon+ r^2}\, d\xi, \quad 0<r<3/4.
		\end{align*}
		Hence $A(r),B(r), H_2(r) \in C^1((0,3/4))$ satisfy, in view of \eqref{FG_bound_2}, that
		\begin{equation}
			\label{AB_bounds}
			|A(r)| \le C(n)r , \quad |B(r)| \le C(n), \quad |H_2(r)|\le C(n)\frac{r^{1+\beta}}{\varepsilon+r^2},\quad 0 < r < 3/4.
		\end{equation}

		\textbf{Step 2.}
		We will prove, for some $\varepsilon$-dependent constant $C_1(\varepsilon)$ and positive $\varepsilon$-independent constant $C_2$, that
		\begin{equation}
			\label{V_11_formula}
			|V_{1,1}(r) - C_1 (\varepsilon) h(r)| \le  C_2 r^{1+\min\{\alpha,\beta\}}, \quad 0<r\le 1/2,
		\end{equation}
		where $h(r)$ is the solution of \eqref{Homogeneous_ODE} satisfying $h(0)=0$, $h(1/2) = 1/2$. We use the method of reduction of order to write down bounded functions $p_1$, $p_2$ satisfying $Lp_i = H_i$ in {$(0,1/2)$}, and then give the estimates $|p_1(r)| \le C r^{1+\alpha}$, $|p_2(r)| \le C r^{1+\beta}$.

		For $i=1,2$, let $p_i = h w_i$ and
		$$
		w_i(r) := \int_0^r\frac{1}{h^2(s) s^{n-2} (\varepsilon + s^2)} \int_0^s h(\tau) \tau^{n-2} (\varepsilon + \tau^2) H_i(\tau) \, d\tau ds, \quad 0 < r \le 1/2.
		$$
		By a direct computation,
		$$
		Lp_i = L(hw_i) = h w_i'' + \left[ 2h' + \left( \frac{n-2}{r} + \frac{2r}{\varepsilon + r^2} \right)h \right]w_i' = \frac{h}{G}(Gw_i')' = {H_i},
		$$
		where $G= h^2 r^{n-2}(\varepsilon + r^2)$. The estimate $|p_1(r)| \le C r^{1+\alpha}$ can be proved in the same way as in Step 2 of the proof of \cite{DongYangZhu26}*{{Theorem} 1.5}. Here we show the estimate $|p_2(r)| \le C r^{1+\beta}$ using the improved estimate \eqref{h_upper_lower}.
		Since $h$ is increasing, by \eqref{AB_bounds}, we have
		\begin{align*}
			|w_2(r)|\le C\int_0^r\frac{1}{h^2(s) s^{n-2} (\varepsilon + s^2)} \int_0^s h(\tau) \tau^{n-1+\beta}  \, d\tau ds\le C\int_0^r\frac{s^{2+\beta}}{h(s)  (\varepsilon + s^2)}\, ds.
		\end{align*}
		Using \eqref{h_upper_lower}, we can estimate that
		$$\frac{s^{2+\beta}}{h(s)  (\varepsilon + s^2)}\le C \frac{s^{2+\beta}}{\varepsilon^\frac{\alpha-1}{2}s\,\varepsilon}\le C s^{\beta-\alpha} \quad \mbox{for } s\in (0,{4}\sqrt{\varepsilon}).$$
		By \eqref{h_lowerbound},  we also have 
		$$\frac{s^{2+\beta}}{h(s)  (\varepsilon + s^2)}\le C \frac{s^{2+\beta}}{s^\alpha\,s^2}\le C s^{\beta-\alpha} \quad \mbox{for } s\in [{4}\sqrt{\varepsilon},1/2].$$
		Therefore, using \eqref{h_bounds},
		\begin{align*}
			|p_2(r)| &=   h(r) |w_2(r)|\le Ch(r)\int_0^r\frac{s^{2+\beta}}{h(s)  (\varepsilon + s^2)}\, ds\\
			&\le Cr^\alpha\int_0^r s^{\beta-\alpha}\,ds\le  Cr^{1+\beta}, \quad\quad 0<r\le 1/2.
		\end{align*}
		Since $V_{1,1} - p_1-p_2$ is bounded and satisfies $L(V_{1,1} - p_1-p_2) = 0$ in $(0,1/2)$ and $V_{1,1}(0) - p_1(0)-p_2(0) = 0$, by Lemma \ref{ODE_lemma}, there exists a constant $C_1(\varepsilon)$ such that \begin{equation*}
			V_{1,1} - p_1-p_2 = C_1(\varepsilon)h.
		\end{equation*}
		Hence \eqref{V_11_formula} follows.

		\textbf{Step 3.} We will show that 
		\begin{equation}\label{C_1_epsilon_lowerbound}
			C_1 (\varepsilon) > \frac{1}{C}
		\end{equation}
		for some positive $\varepsilon$-independent constant $C$.

		By the definition of $\tilde u_+$ in \eqref{subtr} {and the choice of $a$ and $b$},
		$$\tilde u_+=u_++\frac{1}{{2}(\gamma-1)} (\partial_{x_1} g_1(0')+\partial_{x_1}g_2(0'))x_1. $$
		Therefore, by Lemma \ref{linear_lower} and \eqref{est:g_x1_lower}, we have
		$\tilde u_+ \ge x_1$ in $\{x_1 \ge 0\}\cap\widetilde\Omega$ and $\tilde u_+ \le x_1$ in $\{x_1 \le 0\}\cap\widetilde\Omega$. Then
		$$\left\{\begin{aligned}
			&\bar{v}(y') \ge y_1, &&\mbox{when}~y_1\ge 0,\\ 
			&\bar{v}(y') \le y_1, &&\mbox{when}~y_1\le 0.\\ 
		\end{aligned}\right.
		$$
		Recalling that $Y_{1,1}(\xi)=\xi_1/c_n$, we obtain
		$$
		V_{1,1}(r) = \int_{\mathbb{S}^{n-2}}  \bar{v}(r,\xi) Y_{1,1}(\xi) \, d\xi \ge c_n r, \quad 0 < r < 3/4,
		$$
		where $c_n:=(\int_{\mathbb{S}^{n-2}}  {\xi_1^2} d\xi)^{1/2}>0$.
		Combining with \eqref{h_bounds} and \eqref{V_11_formula}, we have
		\begin{align*}
			c_n r \le V_{1,1}(r) \le C_1(\varepsilon)h(r) + \frac{1}{2}c_n r \le C_1(\varepsilon)r^\alpha + \frac{1}{2}c_n r \quad \forall 0 < r \le r_0,
		\end{align*}
		where ${r_0 = \min\{1/2,(c_n/(2C_2))^{1/\min\{\alpha,\beta\}}\}}$. This implies
		$$
		C_1(\varepsilon) \ge \frac{1}{2}c_n r_0^{1-\alpha}.
		$$

		\textbf{Step 4.} Completion of the proof. 

		It follows, in view of \eqref{h_bounds}, \eqref{V_11_formula} and \eqref{C_1_epsilon_lowerbound}, that
		\begin{equation}
			\label{V_11_lowerbound}
			V_{1,1}(r) \ge \frac{1}{C}  h(r) - C_2 r^{1+\min\{\alpha,\beta\}} \ge \frac{1}{2C} h(r) , \quad 0 < r < r_1
		\end{equation}
		for some small $\varepsilon$-independent constant $r_1$. By \eqref{h_lowerbound},
		\begin{equation}
			\label{h1_lowerbound}
			h(2c\sqrt{\varepsilon}) > 2^{\alpha-1}(2^\alpha - 1)c^\alpha \varepsilon^{\alpha/2},
		\end{equation}
		where $c$ is the constant in Lemma \ref{lemma_subsolution}. By \eqref{v_bar_expansion}, \eqref{V_11_lowerbound}, and \eqref{h1_lowerbound}, we have
		\begin{align*}
			\left( \int_{\mathbb{S}^{n-2}} |\bar{v}(2c\sqrt{\varepsilon},\xi)|^2 \, d\xi \right)^{1/2} &\ge |V_{1,1}(2c\sqrt{\varepsilon})| \ge \frac{1}{C} h(2c\sqrt{\varepsilon}) \ge \frac{1}{C}\varepsilon^{\alpha/2} \quad \forall 0 < \varepsilon < \varepsilon_0
		\end{align*}
		for some small positive $\varepsilon_0$ depending only on $n$ and $\gamma$. Then, there exists a $\xi_0 \in \mathbb{S}^{n-2}$ such that $|\bar{v}(2c\sqrt{\varepsilon}, \xi_0)| \ge \frac{1}{C} \varepsilon^{\alpha/2}$. Since $\bar v$ is the vertical average of $v$, and recall that $v(y) = \tilde u_+(x)$, there exists an $x_n \in (-\varepsilon/2 + h_2(x'), \varepsilon/2 + h_1(x'))$ such that
		\begin{equation}
			\label{u_lower_bound}
			|\tilde u_+(2c\sqrt{\varepsilon}, \xi_0, x_n)| \ge \frac{1}{C} \varepsilon^{\frac{\alpha}{2}}.
		\end{equation}
		Estimate \eqref{grad_u_lower_bound} follows from \eqref{u_lower_bound}, $u(0) = 0$, and the fact that $\partial_{x_1} g_i(0')$ is uniformly bounded. This concludes the proof when $n \ge 3$.

		When $n = 2$, by Lemma \ref{lemma_reduction}, $\bar{v}$ satisfies the equation
		$$
		((\varepsilon+|y_1|^2)\bar v')'- 2\gamma^{-1} \bar{v} = F' + {G_1+G_2}\quad \mbox{in}~(-3/4,3/4),
		$$
		where $F$, {$G_1$, and $G_2$} satisfy the same bounds as in \eqref{FG_bound_2}. By using $\bar{v}$ in place of $V_{1,1}$ and repeating steps 2-4 with minor modifications, we can establish the estimate \eqref{grad_u_lower_bound} for $n = 2$.

As in the proof of the case when $\gamma>1/\mu$, we assume that $\mu=1$ and focus on the proof for $n\ge 3$. {We use the same definitions} and notation as those in the previous case when $\gamma>1/\mu$. {Note that in this case, the linear function in \eqref{subtr} is identically equal to zero.}  By Lemma \ref{lemma_reduction}, we know that $\bar{v}$ satisfies the equation \eqref{equation_v_bar}
		$$
		\operatorname{div}((\varepsilon+|y'|^2)\nabla \bar v) - 2\gamma^{-1} \bar{v}(y') = \operatorname{div} F + {G}_1+{G}_2 \quad \mbox{in}~B_{3/4} \subset \mathbb{R}^{n-1}.
		$$
		Since \eqref{prelim_estimate} still holds in this case, by \eqref{FG_bound}, for $|y'|<3/4$ we have
		\begin{equation}\label{FG_bound_3}
			|F(y')| \le C\Big(|y'|(\varepsilon + |y'|^2) + |y'|^4 (\varepsilon +|y'|^2)^{-1/2}\Big), \quad
			|G_1(y')| \le C(\varepsilon + |y'|^2).
		\end{equation} 
		Since $\bar v$ is odd with respect to $y_1$, and in particular $\bar{v}(0) = 0$, we have the decomposition \eqref{v_bar_expansion}.
		Since $\bar{v}(0) = 0$ and $\varepsilon + |y'|^2$ is independent of $\xi$, we know that $V_{1,1}$ satisfies $V_{1,1}(0) = 0$, and
		\begin{equation*}
			LV_{1,1} = H_1(r) + H_2(r), \quad 0 < r <3/4,
		\end{equation*}
		where $L$ is defined in \eqref{def_L},
		\begin{align*}
			H_1(r) &= -\frac{1}{\gamma} \int_{\mathbb{S}^{n-2}} \frac{(\partial_{y_1}g_1(0) + \partial_{y_1}g_2(0))y_1 Y_{1,1}(\xi)}{\varepsilon+r^2} \, d\xi \\
			&= - {c_n}\frac{\partial_{y_1}g_1(0) + \partial_{y_1}g_2(0)}{\gamma} \frac{r}{\varepsilon+r^2},\quad {c_n>0,}
		\end{align*}
		and
		\begin{align*}
			H_2(r) &= \int_{\mathbb{S}^{n-2}} \frac{(\operatorname{div} F + {G_1}) Y_{1,1}(\xi)}{\varepsilon+r^2} \, d\xi\\
			& -\sum_{i=1}^2 \frac{1}{\gamma} \int_{\mathbb{S}^{n-2}} \frac{ \big( \sqrt{1+ |\nabla_{y'}h_i|^2} g_i(y') - \partial_{y_1}g_i(0)y_1 \big) Y_{1,1}(\xi)}{\varepsilon+r^2} \, d\xi\\
			&= \partial_r \left(\int_{\mathbb{S}^{n-2}} \frac{F_r}{\varepsilon + r^2} Y_{1,1}(\xi) \, d\xi \right) + \int_{\mathbb{S}^{n-2}} \Big(\frac{2r}{(\varepsilon+r^2)^2}{+\frac{n-2}{r(\varepsilon+r^2)}}\Big) F_r Y_{1,1}\\
			&\quad - \frac{F_\xi\cdot\nabla_\xi Y_{1,1}}{r(\varepsilon + r^2)} + \frac{{G_1} Y_{1,1}}{\varepsilon+ r^2}\, d\xi\\
			&\quad  -\sum_{i=1}^2 \frac{1}{\gamma} \int_{\mathbb{S}^{n-2}} \frac{ \big( \sqrt{1+ |\nabla_{y'}h_i|^2} g_i(y') - \partial_{y_1}g_i(0)y_1 \big) Y_{1,1}(\xi)}{\varepsilon+r^2} \, d\xi\\
			&=: A'(r) + B(r) + D(r), \quad 0 < r < 3/4.
		\end{align*}
		By \eqref{FG_bound_3}, \eqref{fg_0}, \eqref{def:c_2}, and $\|\nabla g_i\|_{C^{\beta}}\le C/k_i$ as a consequence of \eqref{u-_1+holder},
		one can show that $A(r),B(r), D(r) \in C^1((0,3/4))$ satisfy
		\begin{equation}
			\label{ABD_bounds}
			|A(r)| \le C(n)r, \quad |B(r)| \le C(n), \quad |D(r)| \le C(n,k_1,k_2) \frac{r^{1+\beta}}{\varepsilon+r^2}
		\end{equation}
		for $r\in(0,3/4)$ and $\beta \in(0, 1)$.

		{ Note that $h(r)=r$ is a homogeneous solution for $L$ when $\gamma=1$. One can also use the same method of reduction of order as in the proof of \cite{DongYangZhu26}*{Lemma 7.1} to show that $h(r) = r$ is the unique solution of $Lh=0$ in $(0,1/2)$, such that $h(0)=0$ and $h(1/2)=1/2$.}
		Next, we use the method of reduction of order again to find two bounded particular solutions $p_1$ and $p_2$ satisfying $Lp_i = H_i$ in $(0,1/2)$ for $i = 1,2$. 
		We define
		\begin{align*}
			w_1(r) :=& -\int_r^{\frac{1}{2}}\frac{1}{h^2(s) s^{n-2} (\varepsilon + s^2)} \int_0^s h(\tau) \tau^{n-2} (\varepsilon + \tau^2) H_1(\tau) \, d\tau ds\\
			=& {c_n} \frac{\partial_{y_1}g_1(0) + \partial_{y_1}g_2(0)}{2\gamma (n+1)} \Big[ {\log(\varepsilon + \frac{1}{4})} - \log (\varepsilon + r^2) \Big],
		\end{align*}
		we know that
		$$
		p_1(r) := h(r) w_1(r) = {c_n}\frac{\partial_{y_1}g_1(0) + \partial_{y_1}g_2(0)}{2\gamma (n+1)} r\Big[ \log(\varepsilon + \frac{1}{4}) - \log (\varepsilon + r^2) \Big]
		$$
		is a bounded particular solution to ${L}p_1=H_1$. Using \eqref{ABD_bounds}, we can construct and estimate $|p_2| \le Cr^{1+\min\{\alpha,\beta\}}$ as in the case $\gamma>1$. Then there exists a constant $C_1(\varepsilon)$ such that
		$$
		V_{1,1}(r) = p_1(r) + p_2(r) + C_1(\varepsilon)r.
		$$
		Plugging in $r = 1/2$, we can see that $|C_1(\varepsilon)| \le C$ independent of $\varepsilon$. Therefore, $p_1(r)$ is the leading order term. Namely,
		\begin{equation}\label{V11_lower_2}
		\begin{aligned}
		V_{1,1}(r)&\ge p_1(r)-Cr^{1+\beta}-Cr\\
		&\ge -\frac{{c_n}((1+k_1)^{-1}+(1+k_2)^{-1})}{4\gamma(n+1)}r\log(\varepsilon+r^2),\\
		&\hspace{2em} r\in(0,r_1),\quad {0<\varepsilon<r_1^2}.
		\end{aligned}
		\end{equation}
		where $r_1=r_1(n,\gamma,k_1,k_2)$ is a positive constant independent of $\varepsilon$ {and in the last inequality we used \eqref{est:g_x1_lower}}.
		By \eqref{v_bar_expansion} and \eqref{V11_lower_2}, we have
		\begin{align*}
			\left( \int_{\mathbb{S}^{n-2}} |\bar{v}(\sqrt{\varepsilon},\xi)|^2 \, d\xi \right)^{1/2} &\ge |V_{1,1}(\sqrt{\varepsilon})| \ge -\frac{1}{C} \sqrt{\varepsilon}\log(\varepsilon)\quad \forall 0 < \varepsilon < \varepsilon_0
		\end{align*}
		for some small positive $\varepsilon_0$ depending only on $n$, $\gamma$, $k_1$, $k_2$. Then {arguing as in the case when $\gamma>1/\mu$,}
		{we conclude the proof} when $n \ge 3$.

		When $n = 2$, by Lemma \ref{lemma_reduction}, $\bar{v}$ satisfies the equation
		$$
		((\varepsilon+|y_1|^2)\bar v')'- 2\gamma^{-1} \bar{v} = F' + G_1+G_2\quad \mbox{in}~(-3/4,3/4),
		$$
		where $F$ and $G_1$ satisfy the same bounds as in \eqref{FG_bound_3}. By using $\bar{v}$ in place of $V_{1,1}$ and repeating steps 2-4 with minor modifications, we can establish the estimate \eqref{grad_u_lower_bound_new} for $n = 2$.

For $n \ge 3$, $\varepsilon \in (0,R_0/4)$, $\mu > 0$, let $h_1,h_2$ satisfy \eqref{fg_0}, \eqref{fg_2}, and \eqref{fg_3}. For $i=1,2$, let $\gamma_{i}\in C^{1,1}(\partial\mathcal{D}_i)$ satisfy \eqref{eq9.38}. Let $u$ be the solution of \eqref{robin_variable}. Then there exists a positive universal constant $C$ depending on $\bar{\gamma}$, such that
		\begin{itemize}
			\item when $0 <\bar \gamma < 2/(n\mu)$,
			\begin{equation*}
				|\nabla u(x)| \le C \|\varphi\|_{L^\infty(\partial\Omega)}\quad \mbox{in}~ \Omega_{R_0/2},
			\end{equation*}
			\item when $\bar\gamma = 2/(n\mu)$,
			\begin{equation*}
				|\nabla u(x)| \le C \|\varphi\|_{L^\infty(\partial\Omega)} |\log (\varepsilon+|x'|^2)|\quad \mbox{in}~ \Omega_{R_0/2},
			\end{equation*}
			\item when $\bar\gamma >2/(n\mu)$,
			\begin{equation*}
				|\nabla u(x)| \le C \|\varphi\|_{L^\infty(\partial\Omega)}(\varepsilon + |x'|^2)^{\frac{\alpha_0-1}{2}} \quad \mbox{in}~  \Omega_{R_0/2},
			\end{equation*}
		\end{itemize}
		where $\alpha_0$ is given in \eqref{alpha_n_zero}, with $\gamma$ replaced by $\bar \gamma$.
